<?php
require_once __DIR__.'/../includes/bootstrap.php';require_role('Company');$cid=company_id($pdo);$aid=(int)($_GET['application_id']??$_POST['application_id']??0);$s=$pdo->prepare('SELECT st.name,i.title FROM application a JOIN student st ON st.student_id=a.student_id JOIN internship i ON i.internship_id=a.internship_id WHERE a.application_id=? AND i.company_id=?');$s->execute([$aid,$cid]);$app=$s->fetch();if(!$app)exit('Application not found for this company.');$err='';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$mode=val('mode',30);if(!in_array($mode,['Online','In-person','Phone'],true))$err='Invalid mode.';else{$s=$pdo->prepare('INSERT INTO interview(application_id,interview_date,interview_time,mode,result,remarks) VALUES(?,?,?,?,?,?) ON DUPLICATE KEY UPDATE interview_date=VALUES(interview_date),interview_time=VALUES(interview_time),mode=VALUES(mode),result=VALUES(result),remarks=VALUES(remarks)');$s->execute([$aid,val('interview_date',10)?:null,val('interview_time',8)?:null,$mode,val('result',30)?:null,val('remarks',2000)?:null]);header('Location: applicants.php');exit;}}
$s=$pdo->prepare('SELECT * FROM interview WHERE application_id=?');$s->execute([$aid]);$v=$s->fetch();$b='<h2>Interview: '.e($app['name']).' — '.e($app['title']).'</h2>'.($err?'<p class="error">'.e($err).'</p>':'').'<form method="post"><input type="hidden" name="csrf_token" value="'.e(csrf_token()).'"><input type="hidden" name="application_id" value="'.$aid.'">';
foreach(['interview_date'=>'Date','interview_time'=>'Time','result'=>'Result','remarks'=>'Remarks'] as $k=>$label)$b.='<label>'.e($label).'<input name="'.e($k).'" value="'.e($v[$k]??'').'"></label>';
$b.='<label>Mode<select name="mode"><option>Online</option><option>In-person</option><option>Phone</option></select></label><button>Save interview</button></form>';page('Interview',$b);
